<header class="admin-page-head"><div><p class="eyebrow">Operational view</p><h1>Dashboard</h1></div><a class="button button-small" href="/admin/florist-samples/create">New florist sample</a></header><section class="metric-grid"><article><span>New enquiries</span><strong><?= (int)($counts['New']??0) ?></strong></article><article><span>Awaiting confirmation</span><strong><?= (int)($counts['Awaiting Confirmation']??0) ?></strong></article><article><span>In preparation</span><strong><?= (int)($counts['In Preparation']??0) ?></strong></article><article><span>Ready</span><strong><?= (int)($counts['Ready']??0) ?></strong></article></section><section class="admin-panel"><div class="panel-head"><h2>Recent enquiries</h2></div><?php if($recent): ?><div class="admin-table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Status</th><th>Requested</th><th></th></tr></thead><tbody><?php foreach($recent as $item): ?><tr><td><?= e($item['reference']) ?></td><td><?= e($item['customer_name']) ?><small><?= e($item['customer_phone']) ?></small></td><td><span class="status-badge"><?= e($item['status']) ?></span></td><td><?= e($item['requested_date']) ?></td><td><a href="/admin/enquiries/<?= (int)$item['id'] ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state compact"><p>No enquiries yet.</p></div><?php endif; ?></section>

